import React, { useState } from "react";

function ProductForm({ api, onProductSaved }) {
  const initialState = {
    nome: "",
    preco_compra: "", // USD
    preco_venda: "",  // BRL
    peso: "",         // KG
    iof_percent: "",  // %
    taxa_dolar: "",   // R$
  };

  const [form, setForm] = useState(initialState);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post("/produtos", form);
      alert("Produto cadastrado!");
      setForm(initialState); // Limpa o formulário
      onProductSaved(); // Chama a função do App.js para atualizar a lista
    } catch (error) {
      // Exibe erros da API (como campos faltando)
      const errorMsg = error.response?.data?.erro || "Erro ao salvar produto.";
      alert(errorMsg);
    }
  };

  return (
    <div>
      <h2>Cadastrar Produto</h2>
      <form onSubmit={handleSubmit}>
        <input name="nome" placeholder="Nome" value={form.nome} onChange={handleChange} required />
        <input name="preco_compra" type="number" step="0.01" placeholder="Preço compra (USD)" value={form.preco_compra} onChange={handleChange} required />
        <input name="preco_venda" type="number" step="0.01" placeholder="Preço venda (BRL)" value={form.preco_venda} onChange={handleChange} required />
        <input name="peso" type="number" step="0.01" placeholder="Peso (kg)" value={form.peso} onChange={handleChange} required />
        <input name="iof_percent" type="number" step="0.01" placeholder="IOF (%)" value={form.iof_percent} onChange={handleChange} required />
        <input name="taxa_dolar" type="number" step="0.01" placeholder="Cotação Dólar (R$)" value={form.taxa_dolar} onChange={handleChange} required />
        <button type="submit">Salvar</button>
      </form>
    </div>
  );
}

export default ProductForm;
